def migrer_fils_vers_conversations(apps, schema_editor):
    """Transforme les anciens « fils par employé » en conversations privées.

    Chaque fil devient une conversation entre le créateur de la société et le
    compte relié à l'employé (quand il existe).
    """
    Societe = apps.get_model("gestion", "Societe")
    Employe = apps.get_model("gestion", "Employe")
    EquipeConversation = apps.get_model("gestion", "EquipeConversation")
    EquipeMessage = apps.get_model("gestion", "EquipeMessage")

    fils = (
        EquipeMessage.objects.filter(conversation__isnull=True, employe__isnull=False)
        .values_list("societe_id", "employe_id")
        .distinct()
    )
    societes = {
        s.pk: s for s in Societe.objects.filter(pk__in={f[0] for f in fils})
    }
    for societe_id, employe_id in fils:
        societe = societes.get(societe_id)
        if societe is None:
            continue
        employe = Employe.objects.filter(pk=employe_id).first()
        if employe is None:
            continue
        participants = [societe.createur_id]
        compte_id = employe.compte_id
        if compte_id and compte_id != societe.createur_id:
            participants.append(compte_id)
        conversation = EquipeConversation.objects.create(societe_id=societe_id)
        conversation.participants.add(*participants)
        EquipeMessage.objects.filter(
            societe_id=societe_id,
            employe_id=employe_id,
            conversation__isnull=True,
        ).update(conversation_id=conversation.pk)


